static void writeExport(const std::filesystem::path&dir){std::filesystem::create_directories(dir);sim->statistics().save(dir/L"statistics.json");tissueMetrics(*sim).save(dir/L"metrics.json");std::ofstream cells(dir/L"cells.csv",std::ios::binary);cells<<"id,parent,alive,x,y,radius,biomass,sugar,waste,photosynthesis,sugar_transport,waste_transport,status\r\n"<<std::setprecision(17);for(auto&v:sim->c)cells<<v.id<<','<<v.parent<<','<<v.alive<<','<<v.x<<','<<v.y<<','<<v.r<<','<<v.mass<<','<<v.sugar<<','<<v.waste<<','<<v.photo<<','<<v.ts<<','<<v.tw<<','<<v.status<<"\r\n";std::ofstream network(dir/L"transport_network.csv",std::ios::binary);network<<"cell_a,cell_b,sugar_flux,waste_flux\r\n"<<std::setprecision(17);for(auto&e:sim->edges)network<<sim->c[e.a].id<<','<<sim->c[e.b].id<<','<<e.sugar<<','<<e.waste<<"\r\n";}
